import{_ as p,a0 as t,w as o,s as h,I as n,x as a,a1 as i,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const q=JSON.parse('{"title":"如何使用 Bash history 命令 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Bash history 命令 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Bash history 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Bash history 命令 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20200615 How to use Bash history commands","title":"如何使用 Bash history 命令","tag":"202006","desc":""},"relativePath":"202006/20200615 How to use Bash history commands.md","filePath":"[post].md"}'),d={name:"202006/20200615 How to use Bash history commands.md"};function u(c,s,g,b,k,f){const e=t("Link");return o(),h("div",null,[s[22]||(s[22]=n("h1",{id:"如何使用-bash-history-命令",tabindex:"-1"},[a("如何使用 Bash history 命令 "),n("a",{class:"header-anchor",href:"#如何使用-bash-history-命令","aria-label":"Permalink to “如何使用 Bash history 命令”"},"​")],-1)),s[23]||(s[23]=n("blockquote",null,[n("p",null,"Bash 的 history 命令在它提供的功能數量上超過了所有其他 Linux Shell 歷史接口。")],-1)),s[24]||(s[24]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202006/24/101620c0uj0dgg0buo9nib.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("Bash 有豐富的歷史。也就是説，它是一個古老的的 shell，還有一個更古老的 Shell （Bourne shell）的前輩，但是它還有一個很棒的 ",-1)),s[2]||(s[2]=n("code",null,"history",-1)),s[3]||(s[3]=a(" 命令，它提供的功能數量超過了所有其他 shell 的歷史接口。 ",-1)),i(e,{href:"https://opensource.com/resources/what-bash"},{default:l(()=>[...s[0]||(s[0]=[a("Bash",-1)])]),_:1}),s[4]||(s[4]=a(" 版本的 ",-1)),s[5]||(s[5]=n("code",null,"history",-1)),s[6]||(s[6]=a(" 可進行反向搜索、快速調用、重寫歷史記錄等。",-1))]),s[25]||(s[25]=r(`<p><code>history</code> 命令與許多其他命令不同。你可能習慣於將命令作為可執行文件放在常見的系統級位置，例如 <code>/usr/bin</code>、<code>/usr/local/bin</code> 或者 <code>~/bin</code>。 內置的 <code>history</code> 命令不在你的 <code>PATH</code> 中並且沒有物理位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which history</span></span>
<span class="line"><span></span></span>
<span class="line"><span>which: no history in [PATH]</span></span></code></pre></div><p>相反，<code>history</code> 是 shell 本身的內置函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type history</span></span>
<span class="line"><span>history is a shell builtin</span></span>
<span class="line"><span>$ help history</span></span>
<span class="line"><span>history: history [-c] [-d offset] [n] or</span></span>
<span class="line"><span>history -anrw [filename] or</span></span>
<span class="line"><span>history -ps arg [arg...]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Display or manipulate the history list.</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>出於這個原因，每個 shell 中的歷史功能都是獨特的，因此你在 Bash 中使用的功能可能無法在 Tcsh 或 Fish 或 Dash 中使用，而在這些 shell 中使用的功能可能也無法在 Bash 中使用。在某些情況下，瞭解 Bash 可以做什麼可能會激發其他 shell 的用户創建有趣的改造來複制 Bash 行為，並且可能會解鎖你從未知道的 Bash 功能。</p><h3 id="查看你的-bash-歷史" tabindex="-1">查看你的 Bash 歷史 <a class="header-anchor" href="#查看你的-bash-歷史" aria-label="Permalink to “查看你的 Bash 歷史”">​</a></h3><p><code>history</code> 命令最基本、最頻繁的用法是查看 shell 會話的歷史記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;hello&quot;</span></span>
<span class="line"><span>hello</span></span>
<span class="line"><span>$ echo &quot;world&quot;</span></span>
<span class="line"><span>world</span></span>
<span class="line"><span>$ history</span></span>
<span class="line"><span>  1  echo &quot;hello&quot;</span></span>
<span class="line"><span>  2  echo &quot;world&quot;</span></span>
<span class="line"><span>  3  history</span></span></code></pre></div><h3 id="事件指示器" tabindex="-1">事件指示器 <a class="header-anchor" href="#事件指示器" aria-label="Permalink to “事件指示器”">​</a></h3><p><ruby>事件指示器<rt>Event designator</rt></ruby>按事件搜索你的歷史記錄。在這裏，“事件”是指記錄在歷史中的命令，以換行符劃定。換句話説，一行一個事件，以索引號來標記。</p><p>事件指示器大多以感嘆號開頭，有時也稱為 “bang”（<code>!</code>）。</p><p>要從你的歷史記錄中重新運行命令，請使用感嘆號，之後緊跟（之間沒有空格）所需命令的索引號。例如，假設第 1 行包含命令 <code>echo &quot;hello&quot;</code>，你想要想再次運行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ !1</span></span>
<span class="line"><span>echo &quot;hello&quot;</span></span>
<span class="line"><span>hello</span></span></code></pre></div><p>你可以使用相對定位，提供基於你歷史中當前位置向後的負數行號。例如，返回到歷史中倒數第三個條目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span>
<span class="line"><span>$ echo &quot;bar&quot;</span></span>
<span class="line"><span>bar</span></span>
<span class="line"><span>$ echo &quot;baz&quot;</span></span>
<span class="line"><span>baz</span></span>
<span class="line"><span>$ !-3</span></span>
<span class="line"><span>echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span></code></pre></div><p>如果只想回去一行，那麼可以使用速記 <code>!!</code> 代替 <code>!-1</code>。這節省了按鍵時間！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>$ !!</span></span>
<span class="line"><span>echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span></code></pre></div><h3 id="字符串搜索" tabindex="-1">字符串搜索 <a class="header-anchor" href="#字符串搜索" aria-label="Permalink to “字符串搜索”">​</a></h3><p>你也可以對條目搜索特定的字符串，反過來搜索要運行命令。要搜索以指定字符串<em>開始</em>的命令，請使用感嘆號，之後緊跟（沒有空格）要搜索的字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>$ true</span></span>
<span class="line"><span>$ false</span></span>
<span class="line"><span>$ !echo</span></span>
<span class="line"><span>echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span></code></pre></div><p>你還可以在任意位置（不僅是開頭）搜索包含該字符串的命令。為此，請像之前一樣使用 <code>!</code> 加上要搜索的字符串，但在字符串的兩端都用問號（<code>?</code>）圍繞起來。如果你知道該字符串後緊跟一個換行符，那麼可以省略最後的問號（就是在按<em>回車</em>之前輸入的最後字符）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>$ true</span></span>
<span class="line"><span>$ false</span></span>
<span class="line"><span>$ !?foo?</span></span>
<span class="line"><span>echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span></code></pre></div><h3 id="字符串替換" tabindex="-1">字符串替換 <a class="header-anchor" href="#字符串替換" aria-label="Permalink to “字符串替換”">​</a></h3><p>類似於在行首搜索字符串，你可以搜索字符串並用新字符串替換它，以更改命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;hello&quot;</span></span>
<span class="line"><span>hello</span></span>
<span class="line"><span>$ echo &quot;world&quot;</span></span>
<span class="line"><span>world</span></span>
<span class="line"><span>$ ^hello^foo</span></span>
<span class="line"><span>echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span></code></pre></div><h3 id="讓-history-有用" tabindex="-1">讓 history 有用 <a class="header-anchor" href="#讓-history-有用" aria-label="Permalink to “讓 history 有用”">​</a></h3><p>在 Bash 中，<code>history</code> 命令的功能遠遠超過此處介紹的內容，但這是一個很好的開始, 可以讓你習慣使用你的歷史記錄, 而不是僅僅把它當作一個參考。經常使用 <code>history</code> 命令，並試試無需輸入命令即可執行的操作。你可能會感到驚訝！</p><hr>`,28)),n("p",null,[s[8]||(s[8]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/20/6/bash-history-commands"},{default:l(()=>[...s[7]||(s[7]=[a("https://opensource.com/article/20/6/bash-history-commands",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:l(()=>[...s[9]||(s[9]=[a("Seth Kenlon",-1)])]),_:1}),s[14]||(s[14]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:l(()=>[...s[11]||(s[11]=[a("geekpi",-1)])]),_:1}),s[16]||(s[16]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:l(()=>[...s[18]||(s[18]=[a("Linux中國",-1)])]),_:1}),s[21]||(s[21]=a(" 榮譽推出",-1))])])}const C=p(d,[["render",u]]);export{q as __pageData,C as default};
